/**
 * Generate plugins/types/index.d.ts from src/client/PluginApi.ts
 *
 * This script extracts type definitions from the source code and generates
 * a standalone .d.ts file for external plugin developers. The API interfaces
 * and ClientEvents (src/shared/events/clientEvents.ts) are emitted with every
 * type they reference, and the result must compile on its own or the script
 * fails.
 */

const ts = require('typescript');
const fs = require('fs');
const path = require('path');

const PROJECT_ROOT = path.resolve(__dirname, '..', '..');
const SOURCE_FILE = path.join(PROJECT_ROOT, 'src', 'client', 'PluginApi.ts');
const EVENTS_FILE = path.join(PROJECT_ROOT, 'src', 'shared', 'events', 'clientEvents.ts');
const OUTPUT_FILE = path.join(__dirname, 'index.d.ts');
const TSCONFIG_PATH = path.join(PROJECT_ROOT, 'tsconfig.json');

console.log('🔧 Generating plugin types from source...');
console.log(`📄 Source: ${path.relative(PROJECT_ROOT, SOURCE_FILE)}`);
console.log(`📝 Output: ${path.relative(PROJECT_ROOT, OUTPUT_FILE)}`);

// Read tsconfig
const configFile = ts.readConfigFile(TSCONFIG_PATH, ts.sys.readFile);
const parsedConfig = ts.parseJsonConfigFileContent(
  configFile.config,
  ts.sys,
  PROJECT_ROOT
);

// Create program
const program = ts.createProgram({
  rootNames: [SOURCE_FILE, EVENTS_FILE],
  options: {
    ...parsedConfig.options,
    declaration: true,
    emitDeclarationOnly: true,
    declarationDir: path.join(__dirname, '.temp'),
    noEmit: false
  }
});

const sourceFile = program.getSourceFile(SOURCE_FILE);
if (!sourceFile) {
  console.error('❌ Could not load source file');
  process.exit(1);
}

const checker = program.getTypeChecker();
const output = [];

// Header comment
output.push(`/**
 * TypeScript Type Definitions for Arkadia Web Client Plugins
 *
 * This package provides TypeScript type definitions for developing
 * plugins for the Arkadia Web Client.
 *
 * MAINTAINER NOTE: This file is AUTO-GENERATED from src/client/PluginApi.ts
 * Do not edit this file directly. Run 'yarn build:types' to regenerate.
 *
 * @packageDocumentation
 */
`);

// Track what we've already exported to avoid duplicates
const exportedTypes = new Set();

// Helper to get JSDoc comments
function getJsDocComments(node) {
  const fullText = node.getFullText();
  const jsDocRegex = /\/\*\*[\s\S]*?\*\//g;
  const matches = fullText.match(jsDocRegex);
  return matches ? matches[matches.length - 1] : null;
}

// Helper to check if a type should be exported
function shouldExport(node) {
  // Export interfaces and type aliases
  if (ts.isInterfaceDeclaration(node) || ts.isTypeAliasDeclaration(node)) {
    const name = node.name?.text;

    // Skip internal implementation details
    if (name?.includes('Impl') || name?.includes('Internal')) {
      return false;
    }

    // Export API-related types
    if (name?.endsWith('Api') ||
        name?.endsWith('Handle') ||
        name?.endsWith('Event') ||
        name?.endsWith('Payload') ||
        name?.endsWith('Options') ||
        name?.endsWith('Definition') ||
        name?.endsWith('State') ||
        name?.endsWith('Props') ||
        name === 'PluginApi' ||
        // Plugin UI, storage and waiting
        name === 'PluginReact' ||
        name === 'PluginUiComponents' ||
        name === 'PluginWindowSettingField' ||
        name === 'PluginKeyValueStore' ||
        name === 'WaitForResult' ||
        name === 'HerbBagInspection' ||
        name === 'ContainerCommandForms' ||
        name === 'PluginKeyBind' ||
        name === 'PluginKeyActionOptions' ||
        name === 'PluginInfo' ||
        name === 'Plugin' ||
        name === 'PopupContent' ||
        name === 'PopupSize' ||
        name === 'PluginTooltip' ||
        name === 'PersistentPopupConfig' ||
        name === 'TriggerCallback' ||
        name === 'TriggerMatchFunction' ||
        name === 'TriggerPattern' ||
        name === 'TriggerSubPattern' ||
        name === 'Trigger' ||
        name === 'LocationObject' ||
        name === 'EventKey' ||
        name === 'EventParams' ||
        name === 'EventListener' ||
        // Map overlay types
        name === 'MapOverlayLayer' ||
        name === 'MapOverlayPaint' ||
        name === 'MapOverlayShape' ||
        // Object list filter types
        name === 'ObjectListEntryFilter' ||
        name === 'EntryContext' ||
        name === 'FilterResult' ||
        name === 'EntryStyle' ||
        name === 'EntryContent' ||
        name === 'ObjectData' ||
        // Herb database types
        name === 'HerbsData' ||
        name === 'HerbForms' ||
        name === 'HerbUse' ||
        // Container types
        name === 'ContainerType' ||
        name === 'ContainerForms' ||
        // Magics data types
        name === 'MagicCase' ||
        name === 'MagicForms' ||
        name === 'MagicEntry' ||
        name === 'MagicsFile' ||
        name === 'MagicKeysData') {
      return true;
    }
  }

  return false;
}

// Helper to get JSDoc comments (only the leading JSDoc before the node)
function getLeadingJsDoc(node) {
  const sf = node.getSourceFile();
  const fullText = node.getFullText(sf);
  const nodeText = node.getText(sf);
  const leading = fullText.substring(0, fullText.indexOf(nodeText));

  // Last JSDoc comment (/** ... */) - an earlier one belongs to a section, not this node
  const jsDocMatches = leading.match(/\/\*\*[\s\S]*?\*\//g);
  return jsDocMatches ? jsDocMatches[jsDocMatches.length - 1] : null;
}

// Helper to convert node to string (sf: the file the node, or its original, came from)
function nodeToString(node, sf) {
  const printer = ts.createPrinter({
    newLine: ts.NewLineKind.LineFeed,
    removeComments: false  // Keep comments for interface members
  });

  let result = printer.printNode(ts.EmitHint.Unspecified, node, sf);

  // Remove leading comments from the result (the JSDoc is added separately, a
  // stray line comment would otherwise end up between 'export' and the declaration)
  result = result.replace(/^(\s*)(?:(?:\/\*[\s\S]*?\*\/|\/\/[^\n]*)\s*)+/, '$1');

  // Remove 'export ' keyword if present (TypeScript printer adds it)
  result = result.replace(/^export\s+/, '');

  return result;
}

// ----------------------------------------------------------------------------
// Reachable types
//
// The roots (shouldExport in PluginApi.ts, plus ClientEvents) are emitted along
// with every project type they reference, transitively, so a type the API
// mentions can never be missing from the package. Types already written out by
// hand above are skipped by name.
// ----------------------------------------------------------------------------

const SRC_DIR = path.join(PROJECT_ROOT, 'src') + path.sep;

// Plugins augment these with `declare module ... { interface X {...} }`, which
// only merges with an interface - a type alias is converted on the way out.
const AUGMENTABLE = new Set(['ClientEvents']);

// Ambient global namespaces from src/**/*.d.ts, inlined further down
const AMBIENT_NAMESPACES = new Set(['MapData']);

function isProjectSource(sf) {
  return !sf.isDeclarationFile && path.resolve(sf.fileName).startsWith(SRC_DIR);
}

function isReactDeclaration(sf) {
  return /[\\/]node_modules[\\/]@types[\\/]react[\\/]/.test(sf.fileName);
}

function resolveSymbol(id) {
  let symbol = checker.getSymbolAtLocation(id);
  if (symbol && symbol.flags & ts.SymbolFlags.Alias) symbol = checker.getAliasedSymbol(symbol);
  return symbol;
}

function leftmostIdentifier(name) {
  while (ts.isQualifiedName(name)) name = name.left;
  while (ts.isPropertyAccessExpression(name)) name = name.expression;
  return ts.isIdentifier(name) ? name : null;
}

function isEmittable(decl) {
  return ts.isInterfaceDeclaration(decl) || ts.isTypeAliasDeclaration(decl) || ts.isEnumDeclaration(decl);
}

// Names defined by the hand-written sections already in `output`
function handWrittenNames() {
  const names = new Set();
  for (const m of output.join('\n').matchAll(/^export (?:declare )?(?:interface|type|class|function|namespace|enum) (\w+)/gm)) {
    names.add(m[1]);
  }
  return names;
}

let provided = new Set();
const emitted = new Map();   // name -> symbol
const queue = [];
const problems = [];

function describe(node) {
  const sf = node.getSourceFile();
  const { line } = sf.getLineAndCharacterOfPosition(node.getStart(sf));
  return `${path.relative(PROJECT_ROOT, sf.fileName)}:${line + 1}`;
}

// A default export's symbol is called "default" - use the declared name
function symbolName(symbol) {
  const declared = symbol.declarations?.[0]?.name;
  return declared && ts.isIdentifier(declared) ? declared.text : symbol.getName();
}

function enqueue(symbol, from) {
  const name = symbolName(symbol);
  if (provided.has(name)) return;
  const known = emitted.get(name);
  if (known === symbol) return;
  if (known) {
    problems.push(`two different types are named ${name} (${describe(known.declarations[0])}, ${describe(symbol.declarations[0])})`);
    return;
  }
  const decls = symbol.declarations.filter(d => isProjectSource(d.getSourceFile()));
  if (!decls.length || !decls.every(isEmittable)) {
    problems.push(`${name} (${describe(symbol.declarations[0])}) is referenced from ${describe(from)} but is not an interface, type or enum - write it out by hand or change the reference`);
    return;
  }
  emitted.set(name, symbol);
  queue.push(...decls);
}

// Decide what a type reference refers to: a project type to emit (returns its
// declared name), a React type (`React.X`), or something that needs no output.
function classifyReference(id) {
  const symbol = resolveSymbol(id);
  if (!symbol || !symbol.declarations?.length) return null;
  if (symbol.flags & ts.SymbolFlags.TypeParameter) return null;
  const decl = symbol.declarations[0];
  const sf = decl.getSourceFile();
  if (isProjectSource(sf)) {
    enqueue(symbol, id);
    return symbolName(symbol);
  }
  if (isReactDeclaration(sf) && id.text !== 'React') return `React.${symbolName(symbol)}`;
  return null;
}

function referenceIdentifiers(node) {
  if (ts.isTypeReferenceNode(node)) return leftmostIdentifier(node.typeName);
  if (ts.isExpressionWithTypeArguments(node)) return leftmostIdentifier(node.expression);
  if (ts.isTypeQueryNode(node)) return leftmostIdentifier(node.exprName);
  return null;
}

// `typeof VALUE` has no value to point at in a types-only package. Resolve the
// smallest type around it that no longer needs the value - `keyof typeof X`,
// `(typeof X)[number]` - to what the checker computes, e.g. a literal union.
function valueQueryRoots(decl) {
  const roots = new Set();
  const visit = (node) => {
    if (ts.isTypeQueryNode(node)) {
      const id = leftmostIdentifier(node.exprName);
      const symbol = id && resolveSymbol(id);
      const sf = symbol?.declarations?.[0]?.getSourceFile();
      if (sf && isProjectSource(sf)) {
        let root = node;
        while (ts.isParenthesizedTypeNode(root.parent) || ts.isIndexedAccessTypeNode(root.parent) ||
               (ts.isTypeOperatorNode(root.parent) && root.parent.operator === ts.SyntaxKind.KeyOfKeyword)) {
          root = root.parent;
        }
        roots.add(root);
      }
    }
    ts.forEachChild(node, visit);
  };
  visit(decl);
  return roots;
}

function resolvedTypeNode(node) {
  const flags = ts.NodeBuilderFlags.NoTruncation | ts.NodeBuilderFlags.InTypeAlias;
  const resolved = checker.typeToTypeNode(checker.getTypeFromTypeNode(node), undefined, flags);
  if (!resolved) problems.push(`could not resolve ${node.getText()} at ${describe(node)}`);
  return resolved ?? node;
}

// Rename references to their emitted names (`import {A as B}`, React types),
// resolve value queries, and collect the project types they point at
function rewriteReferences(root, valueRoots) {
  const result = ts.transform(root, [(context) => {
    const visit = (node) => {
      if (valueRoots.has(node)) return resolvedTypeNode(node);
      // import("@shared/x").Name -> Name, emitted like any other reference
      if (ts.isImportTypeNode(node) && !node.isTypeOf && node.qualifier && ts.isIdentifier(node.qualifier)) {
        const target = classifyReference(node.qualifier);
        if (target) {
          const typeArguments = node.typeArguments && ts.visitNodes(node.typeArguments, visit, context);
          return ts.factory.createTypeReferenceNode(target, typeArguments);
        }
      }
      const id = referenceIdentifiers(node);
      if (id) {
        const target = classifyReference(id);
        if (target && target !== id.text) {
          const swap = (n) => n === id
            ? ts.factory.createIdentifier(target)
            : ts.visitEachChild(n, swap, context);
          node = ts.visitEachChild(node, swap, context);
        }
      }
      return ts.visitEachChild(node, visit, context);
    };
    return (n) => ts.visitEachChild(n, visit, context);
  }]);
  return result.transformed[0];
}

// `type X = A & B & { ... }` -> `interface X extends A, B { ... }`
function aliasToInterface(decl) {
  const parts = ts.isIntersectionTypeNode(decl.type) ? decl.type.types : [decl.type];
  const heritage = [];
  const members = [];
  for (const part of parts) {
    if (ts.isTypeReferenceNode(part)) {
      heritage.push(ts.factory.createExpressionWithTypeArguments(part.typeName, part.typeArguments));
    } else if (ts.isTypeLiteralNode(part)) {
      members.push(...part.members);
    } else {
      problems.push(`${decl.name.text} (${describe(decl)}) must be an intersection of named types and type literals to become an interface`);
      return decl;
    }
  }
  const iface = ts.factory.createInterfaceDeclaration(
    decl.modifiers,
    decl.name,
    decl.typeParameters,
    heritage.length ? [ts.factory.createHeritageClause(ts.SyntaxKind.ExtendsKeyword, heritage)] : undefined,
    members
  );
  return ts.setOriginalNode(ts.setTextRange(iface, decl), decl);
}

function emitDeclaration(decl) {
  let node = decl;
  if (ts.isTypeAliasDeclaration(node) && AUGMENTABLE.has(node.name.text)) node = aliasToInterface(node);
  // Wrapped so the transform visits the declaration itself, heritage included
  node = rewriteReferences(ts.factory.createBlock([node]), valueQueryRoots(decl));
  const printed = node.statements.map((s) => nodeToString(s, decl.getSourceFile())).join('\n');
  const jsDoc = getLeadingJsDoc(decl);
  if (jsDoc) output.push('\n' + jsDoc);
  output.push('\nexport ' + printed);
}

function collectRoots(node, roots) {
  if (shouldExport(node)) roots.push(node);
  ts.forEachChild(node, (child) => collectRoots(child, roots));
}

function emitReachableTypes(roots) {
  provided = handWrittenNames();
  for (const root of roots) {
    const symbol = checker.getSymbolAtLocation(root.name);
    if (symbol) enqueue(symbol, root);
  }
  for (let i = 0; i < queue.length; i++) {
    emitDeclaration(queue[i]);
  }
  for (const name of emitted.keys()) exportedTypes.add(name);
}

// Add Plugin interface and PluginInfo first (from comments in original file)
output.push(`
// ============================================================================
// Plugin Interface
// ============================================================================

/**
 * Plugin metadata returned by the init function
 */
export interface PluginInfo {
  /** Name of the plugin */
  name: string;
  /** Version string (e.g., "1.0.0") */
  version: string;
  /** Optional author information */
  author?: string;
  /** Optional description of plugin functionality */
  description?: string;
}

/**
 * Plugin interface that all plugins must implement
 */
export interface Plugin {
  /**
   * Optional stable id, exported from the plugin module:
   * \`export const stableId = 'jubiler';\`
   * The plugin's storage (api.storage) and persistent windows are kept under it
   * instead of its URL, so they survive the plugin moving to another address.
   * 1-64 letters, digits, '.', '_' or '-'; ignored when another loaded plugin uses it.
   */
  stableId?: string;

  /**
   * Initialize the plugin with access to the Plugin API
   * @param api - The Plugin API instance
   * @returns Promise resolving to plugin metadata
   */
  init(api: PluginApi): Promise<PluginInfo>;

  /**
   * Optional cleanup function called when plugin is unloaded
   */
  destroy?(): Promise<void> | void;
}
`);

// Map renderer settings (MapRenderer.Settings, used by map overlays). The
// renderer's Settings.d.ts is self-contained, so it is copied verbatim into a
// namespace instead of making plugin-types depend on mudlet-map-renderer.
const rendererSettingsPath = path.join(
  PROJECT_ROOT, 'node_modules', 'mudlet-map-renderer', 'dist', 'types', 'Settings.d.ts'
);
const rendererSettings = fs.readFileSync(rendererSettingsPath, 'utf-8');
if (/^import /m.test(rendererSettings)) {
  console.error('❌ mudlet-map-renderer Settings.d.ts now has imports - update the MapRenderer namespace inlining');
  process.exit(1);
}
const rendererSettingsBody = rendererSettings
  // Runtime functions have no place in a types-only namespace
  .replace(/^export declare function[^\n]*\n?/gm, '')
  .replace(/^\/\/# sourceMappingURL=.*$/gm, '')
  .trimEnd()
  .split('\n')
  .map((line) => (line ? '  ' + line : line))
  .join('\n');
output.push(`
// ============================================================================
// Map Renderer Types (copied from mudlet-map-renderer)
// ============================================================================

export declare namespace MapRenderer {
${rendererSettingsBody}
}
`);

// MapData (rooms, areas) is an ambient global namespace in the client; the
// package has to export it, since a global would clash with the plugin's own.
const mapDataPath = path.join(PROJECT_ROOT, 'src', 'client', 'types', 'MapData.d.ts');
const mapData = fs.readFileSync(mapDataPath, 'utf-8').replace(/\r\n/g, '\n');
if (/^import /m.test(mapData) || !/^declare namespace MapData \{/m.test(mapData)) {
  console.error('❌ src/client/types/MapData.d.ts changed shape - update the MapData namespace inlining');
  process.exit(1);
}
output.push(`
// ============================================================================
// Map Data Types (from src/client/types/MapData.d.ts)
// ============================================================================

${mapData.trim().replace(/^declare namespace MapData \{/m, 'export declare namespace MapData {')}

// ============================================================================
// Internal Types
// ============================================================================

/**
 * The client instance handed to button and trigger macros. Internal and not
 * part of the plugin API - its shape may change between client versions.
 */
export type Client = any;
`);

// We need to manually add types from dependencies that are referenced
// Add FormatState types
output.push(`
// ============================================================================
// Color Types
// ============================================================================

/**
 * Indexed color (0-255)
 */
export interface IndexedColor {
  space: "indexed";
  index: number;
}

/**
 * RGB color
 */
export interface RgbColor {
  space: "rgb";
  r: number;
  g: number;
  b: number;
}

/**
 * Hexadecimal color
 */
export interface HexColor {
  space: "hex";
  color: string;
}

/**
 * Union type for all color formats
 */
export type FormatColor = IndexedColor | RgbColor | HexColor;

/**
 * Hyperlink with callbacks
 */
export interface FormatHyperlink {
  onClick?: (ev: MouseEvent) => void;
  onContextMenu?: (ev: MouseEvent) => void;
  title?: string;
}

/**
 * Complete formatting state for text
 */
export interface FormatStateSnapshot {
  foreground?: FormatColor;
  background?: FormatColor;
  bold?: boolean;
  italic?: boolean;
  underline?: boolean;
  inverse?: boolean;
  strikethrough?: boolean;
  slowBlink?: boolean;
  rapidBlink?: boolean;
  hyperlink?: FormatHyperlink;
}


/**
 * Text range [start, end] for applying formatting
 */
export type TextRange = [start: number, end: number];

/**
 * Buffer segment with text and optional formatting state
 */
export interface BufferSegment {
  text: string;
  state?: FormatStateSnapshot;
}

// ============================================================================
// AnsiAwareBuffer - Line Manipulation
// ============================================================================

/**
 * Buffer for text with ANSI formatting
 * Represents a line of text with color and style information
 */
export declare class AnsiAwareBuffer {
  /**
   * Create a new AnsiAwareBuffer
   * @param initial - Initial text with ANSI codes, array of segments, or undefined
   * @param state - Optional default formatting state
   *
   * @example
   * // Create empty buffer
   * const buffer = new AnsiAwareBuffer();
   *
   * // Create from plain text
   * const buffer = new AnsiAwareBuffer("Hello world");
   *
   * // Create from text with default formatting
   * const buffer = new AnsiAwareBuffer("Hello", api.colors.fromHex('#ff0000'));
   *
   * // Create from ANSI string
   * const buffer = new AnsiAwareBuffer("\\x1b[31mRed text\\x1b[0m");
   *
   * // Create from segments
   * const segments: BufferSegment[] = [
   *   { text: "Hello ", state: api.colors.fromHex('#00ff00') },
   *   { text: "world", state: api.colors.fromHex('#0000ff') }
   * ];
   * const buffer = new AnsiAwareBuffer(segments);
   */
  constructor(initial?: string | BufferSegment[], state?: FormatStateSnapshot);
  /**
   * Get the plain text content without formatting
   */
  readonly text: string;

  /**
   * Get the total character length
   */
  readonly length: number;

  /**
   * Create a deep copy of this buffer
   */
  clone(): AnsiAwareBuffer;

  /**
   * Clear all content from the buffer
   */
  clear(): this;

  /**
   * Replace text in a range
   * @param range - [start, end] indices
   * @param text - New text to insert
   * @param state - Optional formatting to apply
   */
  replace(range: TextRange, text: string, state?: FormatStateSnapshot): this;

  /**
   * Insert text at an index
   * @param index - Position to insert at
   * @param text - Text to insert
   * @param state - Optional formatting to apply
   */
  insert(index: number, text: string, state?: FormatStateSnapshot): this;

  /**
   * Insert another buffer at an index
   * @param index - Position to insert at
   * @param buffer - Buffer to insert
   */
  insertBuffer(index: number, buffer: AnsiAwareBuffer): this;

  /**
   * Append another buffer to the end
   * @param buffer - Buffer to append
   */
  appendBuffer(buffer: AnsiAwareBuffer): this;

  /**
   * Prepend another buffer to the beginning
   * @param buffer - Buffer to prepend
   */
  prependBuffer(buffer: AnsiAwareBuffer): this;

  /**
   * Add text to the beginning of the line
   * @param text - Text to prepend
   * @param state - Optional formatting to apply
   */
  prepend(text: string, state?: FormatStateSnapshot): this;

  /**
   * Add text to the end of the line
   * @param text - Text to append
   * @param state - Optional formatting to apply
   */
  append(text: string, state?: FormatStateSnapshot): this;

  /**
   * Apply color/formatting to a text range
   * @param range - [start, end] indices
   * @param color - Color index (0-255) or full FormatStateSnapshot
   */
  color(range: TextRange, color: number | FormatStateSnapshot): this;

  /**
   * Apply color/formatting to specific words throughout the buffer
   * @param words - Single word or array of words to colorize
   * @param color - Color index (0-255) or full FormatStateSnapshot
   * @param options - Search options (caseInsensitive)
   *
   * @example
   * \`\`\`typescript
   * // Color a single word
   * line.colorWords("gold", api.colors.fromHex('#ffd700'));
   *
   * // Color multiple words
   * line.colorWords(["red", "blue"], 196, { caseInsensitive: true });
   * \`\`\`
   */
  colorWords(
    words: string | string[],
    color: number | FormatStateSnapshot,
    options?: { caseInsensitive?: boolean }
  ): this;

  /**
   * Make a text range clickable with event handlers
   * @param range - [start, end] indices
   * @param options - Link options (onClick, onContextMenu, title)
   *
   * @example
   * \`\`\`typescript
   * const text = "Click here";
   * const start = line.text.indexOf(text);
   * line.createLink([start, start + text.length], {
   *   onClick: () => api.output.print("Clicked!", "system"),
   *   title: "Click to execute"
   * });
   * \`\`\`
   */
  createLink(
    range: TextRange,
    options: {
      onClick?: (ev: MouseEvent) => void;
      onContextMenu?: (ev: MouseEvent) => void;
      title?: string;
    }
  ): this;

  /**
   * Make all occurrences of a text string clickable
   * @param text - Text to make clickable
   * @param options - Link options (onClick, onContextMenu, title)
   * @param searchOptions - Search options (caseInsensitive)
   *
   * @example
   * \`\`\`typescript
   * line.createLinksForText("potion", {
   *   onClick: () => api.output.print("Use potion", "system"),
   *   title: "Click to use"
   * }, { caseInsensitive: true });
   * \`\`\`
   */
  createLinksForText(
    text: string,
    options: {
      onClick?: (ev: MouseEvent) => void;
      onContextMenu?: (ev: MouseEvent) => void;
      title?: string;
    },
    searchOptions?: { caseInsensitive?: boolean }
  ): this;

  /**
   * Remove text in a range
   * @param range - [start, end] indices
   */
  remove(range: TextRange): this;
  
  /**
     * Returns the format state at the given character index.
     * This includes color information (foreground, background) and other formatting attributes.
     * Returns undefined if the character at that index has no formatting.
     */
    getStateAt(index: number): FormatStateSnapshot | undefined;
}

// ============================================================================
// Trigger System
// ============================================================================

/**
 * Callback function for triggers
 * @param line - The line buffer to potentially modify
 * @param matches - Regex match results
 * @param type - Line type (e.g., "prompt", "info", "error")
 * @returns Modified line or null to suppress the line
 */
export type TriggerCallback = (
  line: AnsiAwareBuffer,
  matches: RegExpMatchArray,
  type: string
) => AnsiAwareBuffer | null;

/**
 * Custom match function for advanced trigger patterns
 */
export type TriggerMatchFunction = (
  line: AnsiAwareBuffer,
  matches: RegExpMatchArray,
  type: string
) => RegExpMatchArray | undefined;

/**
 * Trigger pattern types
 */
export type TriggerSubPattern = string | RegExp | TriggerMatchFunction;
export type TriggerPattern = TriggerSubPattern | TriggerSubPattern[];

/**
 * Options for trigger behavior
 */
export interface TriggerOptions {
  /** Number of lines to keep child triggers active after parent matches */
  stayOpenLines?: number;
  /** Make regex case-insensitive */
  caseInsensitive?: boolean;
}

/**
 * Trigger instance
 */
export interface Trigger {
  /** Unique trigger ID */
  readonly id: string;

  /**
   * Register a child trigger (active after parent matches)
   * @param pattern - Pattern(s) to match
   * @param callback - Function to call on match
   * @param tag - Optional tag for grouping/removal
   * @param options - Trigger options
   */
  registerChild(
    pattern: TriggerPattern,
    callback?: TriggerCallback,
    tag?: string,
    options?: TriggerOptions
  ): Trigger;

  /**
   * Register a one-time child trigger (auto-removed after first match)
   * @param pattern - Pattern(s) to match
   * @param callback - Function to call on match
   * @param tag - Optional tag for grouping/removal
   * @param options - Trigger options
   */
  registerOneTimeChild(
    pattern: TriggerPattern,
    callback: TriggerCallback,
    tag?: string,
    options?: TriggerOptions
  ): Trigger;
}

/**
 * Helper function to match on line type
 * @param type - Line type to match (e.g., "prompt", "info")
 */
export function isType(type: string): TriggerMatchFunction;

// ============================================================================
// Map Position
// ============================================================================

/**
 * Map direction type
 */
export type MapDirection =
  | "north"
  | "south"
  | "east"
  | "west"
  | "northwest"
  | "northeast"
  | "southeast"
  | "southwest"
  | "up"
  | "down"
  | "in"
  | "out";

/**
 * Map room information
 */
export interface Room {
  /** Room ID */
  id: number;
  /** Area ID (numeric) */
  area: number;
  /** X coordinate */
  x: number;
  /** Y coordinate */
  y: number;
  /** Z coordinate (level) */
  z: number;
  /** Area identifier string */
  areaId: string;
  /** Room name */
  name: string;
  /** Room weight for pathfinding */
  weight: number;
  /** Room symbol */
  symbol: string;
  /** User-defined data */
  userData: Record<string, string>;
  /** Custom lines */
  customLines: Record<string, any>;
  /** Stub exits */
  stubs: number[];
  /** Room hash */
  hash: string;
  /** Environment ID */
  env: number;
  /** Exit connections to room IDs */
  exits: Record<MapDirection, number>;
  /** Door types (1=open, 2=closed, 3=locked) */
  doors: Record<MapDirection, 1 | 2 | 3>;
  /** Special exits with custom commands */
  specialExits: Record<string, number>;
}

// ============================================================================
// Object List Filter Types
// ============================================================================

/**
 * Object data from GMCP
 */
export interface ObjectData {
  num: number;
  id?: string;
  desc?: string;
  hp?: number;
  maxhp?: number;
  image?: string;
  attackers?: { num: number; id?: string }[];
}

/**
 * Entry context provided to filters
 */
export interface EntryContext {
  /** The object data from GMCP */
  object: ObjectData;
  /** The display number/shortcut for this entry */
  displayNum: number;
  /** Whether this is the avatar's current target */
  isTarget: boolean;
  /** Whether this is the avatar's next target in queue */
  isNextTarget: boolean;
  /** Whether this object is a team member */
  isTeammate: boolean;
  /** The raw description text */
  rawDescription: string;
  /** Whether this object is currently attacking */
  isAttacking: boolean;
  /** Current attack command being used */
  attackCommand: string;
}

/**
 * Entry style modifications
 */
export interface EntryStyle {
  /** Color for the description text (CSS color value) */
  descriptionColor?: string;
  /** Whether to apply italic style to description */
  italic?: boolean;
  /** Color for the HP bar (CSS color value) */
  hpBarColor?: string;
  /** Additional CSS class names to add to the entry */
  cssClasses?: string[];
  /** Custom prefix to add before the entry (e.g., icons, indicators) */
  prefix?: string;
  /** Custom suffix to add after the entry */
  suffix?: string;
}

/**
 * Entry content modifications
 */
export interface EntryContent {
  /** Modified description text (replaces original if provided) */
  description?: string;
  /** Modified HP display (replaces original if provided) */
  hpBar?: string;
  /** Modified number label (replaces original if provided) */
  numberLabel?: string;
}

/**
 * Filter result - mutate this object to modify the entry
 */
export interface FilterResult {
  /** Style modifications - mutate this object to add/change styles */
  style: EntryStyle;
  /** Content modifications - mutate this object to replace content */
  content: EntryContent;
  /** If true, prevents subsequent filters from running */
  stopPropagation?: boolean;
}

/**
 * Object list entry filter function
 *
 * Receives context about the entry and the current accumulated result from previous filters.
 * Filters modify the result object directly and optionally return { stopPropagation: true }.
 *
 * @param context - Information about the object being rendered
 * @param result - Current accumulated style and content (mutate this object)
 * @returns void or { stopPropagation: true } to prevent further filters
 *
 * @example
 * \`\`\`typescript
 * const highlightDragons: ObjectListEntryFilter = (context, result) => {
 *   if (context.rawDescription.toLowerCase().includes("smok")) {
 *     result.style.descriptionColor = "#ff0000";
 *     result.style.prefix = (result.style.prefix || "") + "🐉 ";
 *   }
 * };
 *
 * api.objectListFilters.register("dragons", highlightDragons, 10);
 * \`\`\`
 */
export type ObjectListEntryFilter = (
  context: EntryContext,
  result: FilterResult
) => void | { stopPropagation: true };

// ============================================================================
// Live Map Edit Types
// ============================================================================

/**
 * A single room's worth of live map edits, as accepted by \`api.map.applyChanges\`.
 * Only the fields present are touched; everything else on the room is left alone.
 */
export interface RoomChange {
  /** Room to patch. Ignored if the map has no such room. */
  roomId: number;
  /**
   * What to do with the room:
   * - \`patch\` (default) — update an existing room, skip if it is missing.
   * - \`upsert\` — update, or create it when missing. Needs \`area\`.
   * - \`delete\` — remove the room from the map entirely.
   */
  op?: 'patch' | 'upsert' | 'delete';
  /** Area to place a newly created room in. Only read when upserting. */
  area?: number;
  /** Room name. */
  name?: string;
  /** Symbol drawn in the room square (Mudlet's roomChar). */
  roomChar?: string;
  /** Environment/colour id. */
  env?: number;
  /** Pathfinding weight. */
  weight?: number;
  /** Map coordinates. Moving a room needs the area geometry rebuild. */
  x?: number;
  y?: number;
  z?: number;
  /** Replaces the room's exits wholesale. */
  exits?: Partial<Record<MapDirection, number>>;
  /** Replaces the room's special exits wholesale. */
  specialExits?: Record<string, number>;
  /** Merged into existing userData; a \`null\` value removes that key. */
  userData?: Record<string, string | null>;
}

/**
 * The whole map, as published in \`mapExport.json\`: an array of areas with
 * coordinates in source orientation. Accepted by \`api.map.replaceMap\`.
 */
export type MapExportData = MapAreaData[];

/**
 * One area in the shape the renderer consumes — the same objects found in the
 * published \`mapExport.json\`. Coordinates are in source orientation (y-up, as
 * Mudlet stores them); \`api.map.syncAreas\` flips y on the way in, exactly as the
 * map does when it first loads.
 */
export interface MapAreaData {
  areaId: string | number;
  areaName?: string;
  rooms: MapData.Room[];
  labels?: unknown[];
}

/**
 * Tuning for \`api.map.applyChanges\`. Every rebuild defaults to \`true\`, which is
 * always correct but heavier than a cosmetic edit needs.
 */
export interface ApplyChangesOptions {
  /**
   * Rebuild renderer geometry for affected areas. Required for anything that
   * changes what is drawn (symbols, colours, exits). Default \`true\`.
   */
  rebuildAreas?: boolean;
  /**
   * Rebuild the pathfinder. Only exits and weights affect routing, so a pure
   * name/symbol change can skip it. Default \`true\`.
   */
  rebuildPaths?: boolean;
  /** Redraw the current view when done. Default \`true\`. */
  rerender?: boolean;
}

// ============================================================================
// Enemy Bind Resolver Types
// ============================================================================

/**
 * A single enemy candidate eligible for a bind slot (F1/F2/F3)
 */
export interface EnemyBindCandidate {
  /** Object number (matches the GMCP object id; bind with \`ob_<num>\`) */
  num: number;
  /** Object description/name as shown in the bind line */
  desc: string;
}

/**
 * Read-only view of an object on the current location, passed to resolvers
 */
export interface EnemyBindLocationObject {
  num: number;
  desc?: string;
  hp?: number;
  attack_num?: boolean | number;
  shortcut?: string;
  __category?: "player" | "team" | "rest" | "rest-noncombat";
}

/**
 * Enemy bind resolver function
 *
 * Receives the current (ordered) candidate list and every object on the location,
 * and returns the candidate list to use going forward. Return a reordered and/or
 * extended array to change which enemies get bound, or nothing to leave it unchanged.
 *
 * Resolvers compose: the output of one becomes the \`candidates\` input of the next,
 * in priority order (higher priority runs first).
 *
 * @param candidates - Current ordered candidate list (output of previous resolvers)
 * @param allObjects - Every object on the current location
 */
export type EnemyBindResolver = (
  candidates: EnemyBindCandidate[],
  allObjects: EnemyBindLocationObject[]
) => EnemyBindCandidate[] | void;
`);


